1366	// replaceTranscript writes the full transcript content, replacing any existing transcript.
1367	// Also removes any chunk files from a previous write and updates the content hash.
1368	func (s *GitStore) replaceTranscript(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) error {
1369		// Remove existing transcript files (base + any chunks)
1370		transcriptBase := sessionPath + paths.TranscriptFileName
1371		for key := range entries {
1372			if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
1373				delete(entries, key)
1374			}
1375		}
1376	
1377		// Chunk the transcript (matches writeTranscript behavior)
1378		chunks, err := agent.ChunkTranscript(ctx, transcript.Bytes(), agentType)
1379		if err != nil {
1380			return fmt.Errorf("failed to chunk transcript: %w", err)
1381		}
1382	
1383		// Write chunk files
1384		for i, chunk := range chunks {
1385			chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
1386			blobHash, err := CreateBlobFromContent(s.repo, chunk)
1387			if err != nil {
1388				return fmt.Errorf("failed to create transcript blob: %w", err)
1389			}
1390			entries[chunkPath] = object.TreeEntry{
1391				Name: chunkPath,
1392				Mode: filemode.Regular,
1393				Hash: blobHash,
1394			}
1395		}
1396	
1397		// Update content hash
1398		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
1399		hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
1400		if err != nil {
1401			return fmt.Errorf("failed to create content hash blob: %w", err)
1402		}
1403		hashPath := sessionPath + paths.ContentHashFileName
1404		entries[hashPath] = object.TreeEntry{
1405			Name: hashPath,
1406			Mode: filemode.Regular,
1407			Hash: hashBlob,
1408		}
1409	
1410		return nil
1411	}
