1493	// CreateBlobFromContent creates a blob object from in-memory content.
1494	// Exported for use by strategy package (session_test.go)
1495	func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1496		obj := repo.Storer.NewEncodedObject()
1497		obj.SetType(plumbing.BlobObject)
1498		obj.SetSize(int64(len(content)))
1499	
1500		writer, err := obj.Writer()
1501		if err != nil {
1502			return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1503		}
1504	
1505		_, err = writer.Write(content)
1506		if err != nil {
1507			_ = writer.Close()
1508			return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1509		}
1510		if err := writer.Close(); err != nil {
1511			return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1512		}
1513	
1514		hash, err := repo.Storer.SetEncodedObject(obj)
1515		if err != nil {
1516			return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1517		}
1518		return hash, nil
1519	}
